"""Unit 4.4: original mechanism diagrams and evidence-led captions."""
from atlas_figures import shell
from unit4_mobile import drawing as mobile_drawing

LESSONS = [
    {'title': 'Visibility needs a synchronization edge', 'caption': 'The writer initializes the result and releases a mutex. The reader acquires that same mutex and reads the result. Under the language’s mutex rules, the write happens before the protected read; elapsed time alone supplies no such guarantee.'},
    {'title': 'Immutable sharing and guarded mutation', 'caption': 'The immutable result can be read after safe publication without protecting further writes to that result. The mutable counter needs a protocol for every access. An immutable reference alone does not freeze its target object.'},
    {'title': 'When arrivals exceed service capacity', 'caption': 'With a constant excess of 50 jobs per second and an initially empty queue, waiting work reaches 100 after two seconds in this illustrative fluid model. At capacity, reject or defer input; a bounded queue does not increase completion rate.'},
    {'title': 'Cancellation propagates through a task family', 'caption': 'Cancellation reaches children in the parent’s task scope. The scope waits for their cleanup under the runtime’s rules. An upload may already have caused an external effect, so stopping its task is not a business rollback.'},
]

